MAX_ATTEMPTS = 3



def retry_count(attempts):
    return max(0, attempts - 1)


def send_with_retry(send, payload):
    attempts = 0
    while attempts < MAX_ATTEMPTS:
        attempts += 1
        try:
            result = send(payload)
            return result, retry_count(attempts)
        except TimeoutError:
            if attempts == MAX_ATTEMPTS:
                raise
    return None

